// solve.js — native N-API site generator (site-gen-native).
// The whole pipeline runs in C (addon.node). run(input) keeps the
// contract: a parsed case object (or a JSON string / Uint8Array) -> output
// object. main.ts uses runAllBytes() on the raw cases.json bytes to skip
// the JS JSON.parse/JSON.stringify round-trip entirely.
import { createRequire } from 'node:module';
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';

const ADDON_B64 = '';
const addonBuf = Buffer.from(ADDON_B64, 'base64');
// Write the native addon to disk (dlopen needs a real file). Prefer the
// directory next to solve.js; fall back to the OS temp dir if read-only.
let addonPath;
const here = dirname(fileURLToPath(import.meta.url));
try {
  addonPath = join(here, 'addon.node');
  writeFileSync(addonPath, addonBuf);
} catch {
  addonPath = join(tmpdir(), 'sitegen-addon.node');
  writeFileSync(addonPath, addonBuf);
}
const require = createRequire(import.meta.url);
const addon = require(addonPath);

// ---- JS slugify (v8b, ground truth) — used only by the native fallback
// for strings holding a non-ASCII char outside the C NFKD table.
const HAS_NONASCII = /[^\x00-\x7F]/;
function slugifyJs(text) {
  if (!HAS_NONASCII.test(text)) {
    let out = '';
    let gap = false;
    for (let i = 0; i < text.length; i++) {
      const c = text.charCodeAt(i);
      let keep = -1;
      if (c >= 65 && c <= 90) keep = c + 32;
      else if ((c >= 97 && c <= 122) || (c >= 48 && c <= 57)) keep = c;
      if (keep === -1) {
        gap = out.length > 0;
        continue;
      }
      if (gap) out += '-';
      gap = false;
      out += String.fromCharCode(keep);
    }
    if (out.length > 64) out = out.slice(0, 64);
    out = out.replace(/-+$/, '');
    if (out === '') out = 'untitled';
    return out;
  }
  const plain = text.normalize('NFKD').replace(/\p{M}/gu, '');
  let out = '';
  let gap = false;
  for (const ch of plain) {
    let keep = null;
    if (ch >= 'A' && ch <= 'Z') keep = ch.toLowerCase();
    else if ((ch >= 'a' && ch <= 'z') || (ch >= '0' && ch <= '9')) keep = ch;
    if (keep === null) {
      gap = out.length > 0;
      continue;
    }
    if (gap) out += '-';
    gap = false;
    out += keep;
  }
  out = out.slice(0, 64).replace(/-+$/, '');
  if (out === '') out = 'untitled';
  return out;
}

addon.setSlugifyFallback(slugifyJs);

const utf8Decoder = new TextDecoder();
const utf8Encoder = new TextEncoder();

// ---- the run() contract: parsed object (or string/bytes) -> output object ----
export function run(input) {
  let json;
  if (typeof input === 'string') json = input;
  else if (input instanceof Uint8Array) json = utf8Decoder.decode(input);
  else json = JSON.stringify(input);
  return JSON.parse(addon.runOneJson(json));
}

// ---- fast path for main.ts: whole cases.json bytes -> answers JSON bytes ----
export function runAllBytes(inputBytes) {
  const buf = Buffer.isBuffer(inputBytes)
    ? inputBytes
    : Buffer.from(inputBytes instanceof Uint8Array ? inputBytes : utf8Encoder.encode(String(inputBytes)));
  return addon.runAllBytes(buf);
}

// ---- test access ----
export function getAddon() {
  return addon;
}
